    enonce: "<span class=\"q\">1) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = -a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2</span> حيث <span dir=\"ltr\" class=\"expr\">M = (√2 - 4) - [-a + (a - √2)] + [a + a - a] + √2 - 2a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - 2√2</span><br><span class=\"q\">2) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = -a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2</span> حيث أوجد a إذا علمت أنّ <span dir=\"ltr\" class=\"expr\">|M + 4| = 1</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = -a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2</span><br><span class=\"q\">3) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = -a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2</span> حيث أوجد a إذا علمت أنّ <span dir=\"ltr\" class=\"expr\">|M + 4| = 1</span> علما أنّ أوجد y إن أمكن ذلك، إذا علمت أنّ <span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - |y| = -2</span><br><span class=\"q\">4) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = -a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2</span> حيث أوجد a إذا علمت أنّ <span dir=\"ltr\" class=\"expr\">|M + 4| = 1</span> علما أنّ أوجد y إن أمكن ذلك، إذا علمت أنّ أوجد <span dir=\"ltr\" class=\"expr\">|a|</span> <span dir=\"ltr\" class=\"expr\">M + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> = √2</span> <span dir=\"ltr\" class=\"expr\">M = -a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = √2 - 4 + a - a + √2 + a + a - a + √2 - 2a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - 2√2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = (a - a + a + a - a - 2a) + (-4 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span>) + (√2 + √2 + √2 - 2√2)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = -a - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + √2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"من أجل r موجب، <span dir=\"ltr\" class=\"expr\">|X| = r</span> يعني <span dir=\"ltr\" class=\"expr\">X = r</span> أو <span dir=\"ltr\" class=\"expr\">X = -r ؛</span> و إذا كان r سالبا فلا حلّ"},{"quoi":"نكتب ما بداخل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">M + 4 = -a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √2</span>"},{"quoi":"الحالة الأولى","math":"<span dir=\"ltr\" class=\"expr\">-a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √2 = 1</span>"},{"quoi":"الحلّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √2</span>"},{"quoi":"الحالة الثانية","math":"<span dir=\"ltr\" class=\"expr\">-a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √2 = -1</span>"},{"quoi":"الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + √2</span>"},{"quoi":"النتيجة","math":"للمعادلة حلاّن اثنان"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نعزل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + 2 = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">|y| = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"القاعدة","math":"من أجل r موجب، <span dir=\"ltr\" class=\"expr\">|X| = r</span> يعني <span dir=\"ltr\" class=\"expr\">X = r</span> أو <span dir=\"ltr\" class=\"expr\">X = -r</span>"},{"quoi":"الحلّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">y = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"للمعادلة حلاّن متقابلان"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-a - <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">4</span></span> + √2 = √2</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">4</span></span></span>"},{"quoi":"نحدّد الإشارة","math":"العدد <span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">4</span></span></span> هو عدد سالب تقريبا يساوي <span dir=\"ltr\" class=\"expr\">-3.25</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد موجب هي هو نفسه، و لعدد سالب هي مقابله"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">|a| = <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">4</span></span></span>"}],
